description:
Implement a `useWindowSize` hook that returns the current `{ width, height }` of the browser window and updates the values whenever a `resize` event fires.

**Example:**
```tsx
const { width, height } = useWindowSize();
return <p>{width} x {height}</p>;
```

starter_code:
import { useEffect, useState } from 'react';

export function useWindowSize(): { width: number; height: number } {
  // your code here
}

test_suite:
test('returns numeric width and height', () => {
  const { result } = renderHook(() => useWindowSize());
  expect(typeof result.current.width).toBe('number');
  expect(typeof result.current.height).toBe('number');
});

test('updates when resize event fires', () => {
  const { result } = renderHook(() => useWindowSize());
  act(() => {
    Object.defineProperty(window, 'innerWidth', { writable: true, configurable: true, value: 1024 });
    Object.defineProperty(window, 'innerHeight', { writable: true, configurable: true, value: 768 });
    window.dispatchEvent(new Event('resize'));
  });
  expect(result.current.width).toBe(1024);
  expect(result.current.height).toBe(768);
});

test('removes resize listener on unmount', () => {
  const spy = vi.spyOn(window, 'removeEventListener');
  const { unmount } = renderHook(() => useWindowSize());
  unmount();
  expect(spy).toHaveBeenCalledWith('resize', expect.any(Function));
  spy.mockRestore();
});

// __hidden__
test('initial values match window dimensions', () => {
  Object.defineProperty(window, 'innerWidth', { writable: true, configurable: true, value: 800 });
  Object.defineProperty(window, 'innerHeight', { writable: true, configurable: true, value: 600 });
  const { result } = renderHook(() => useWindowSize());
  expect(result.current.width).toBe(800);
  expect(result.current.height).toBe(600);
});

solution:
import { useEffect, useState } from 'react';

export function useWindowSize(): { width: number; height: number } {
  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight });

  useEffect(() => {
    const handler = () => setSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);

  return size;
}
